#!/usr/bin/env python3
"""Atlas descritivo paulista: TSE nominal, IBGE e economia municipal.

Não estima transferência individual nem prioridades de campanha.
Votos de deputados usam a coluna nominal, preservando a votação recebida
mesmo quando o arquivo atualizado contém anulação posterior.
"""

import csv
import gzip
import io
import json
import re
import unicodedata
import zipfile
from collections import Counter, defaultdict
from pathlib import Path
from urllib.request import Request, urlopen

ROOT = Path(__file__).resolve().parents[1]
BASE = ROOT / "data/pesquisas/estaduais/sp/2026-09"
PUBLIC = ROOT / "docs/assets"
URLS = {
    "localidades": "https://servicodados.ibge.gov.br/api/v1/localidades/estados/35/municipios",
    "malha": "https://servicodados.ibge.gov.br/api/v3/malhas/estados/35?formato=application/vnd.geo+json&qualidade=minima&intrarregiao=municipio",
    "renda": "https://apisidra.ibge.gov.br/values/t/10295/n6/in%20n3%2035/v/13431/p/2022?formato=json",
    "populacao": "https://apisidra.ibge.gov.br/values/t/4714/n6/in%20n3%2035/v/93/p/2022?formato=json",
}
NAMES = {
    "EDUARDO BOLSONARO": "eduardo",
    "CARLA ZAMBELLI": "carla",
    "MARIO FRIAS": "mario",
    "GIL DINIZ": "gil",
}


def norm(s):
    text = re.sub(
        r"[^A-Z0-9]+",
        " ",
        unicodedata.normalize("NFKD", s).encode("ascii", "ignore").decode().upper(),
    ).strip()
    return {
        "SAO LUIS DO PARAITINGA": "SAO LUIZ DO PARAITINGA",
        "EMBU": "EMBU DAS ARTES",
        "BIRITIBA MIRIM": "BIRITIBA MIRIM",
    }.get(text, text)


def cached(name, url):
    path = BASE / "fontes" / f"{name}.json"
    if not path.exists():
        path.write_bytes(
            urlopen(
                Request(url, headers={"User-Agent": "Arvor research"}), timeout=180
            ).read()
        )
    payload = path.read_bytes()
    if payload[:2] == b"\x1f\x8b":
        payload = gzip.decompress(payload)
    return json.loads(payload)


def geography():
    cities = {}
    for r in cached("localidades", URLS["localidades"]):
        cities[norm(r["nome"])] = {
            "id": str(r["id"]),
            "nome": r["nome"],
            "regiao": r["regiao-imediata"]["regiao-intermediaria"]["nome"],
        }
    byid = {r["id"]: r for r in cities.values()}
    for kind in ("renda", "populacao"):
        for r in cached(kind, URLS[kind])[1:]:
            byid[r["D1C"]][kind] = (
                float(r["V"]) if r["V"] not in ("...", "-", "X") else None
            )
    geo = cached("malha", URLS["malha"])
    (PUBLIC / "sp_092026_municipios.geojson").write_text(
        json.dumps(geo, separators=(",", ":"))
    )
    assert len(cities) == 645
    return cities


def elections(cities):
    totals = defaultdict(Counter)
    audit = {}
    for year in (2018, 2022):
        path = ROOT / f"data/raw/tse_resultados/votacao_candidato_munzona_{year}.zip"
        with zipfile.ZipFile(path) as z:
            for suffix in ("SP", "BR"):
                member = next(
                    n for n in z.namelist() if n.endswith(f"_{year}_{suffix}.csv")
                )
                with z.open(member) as raw:
                    for row in csv.DictReader(
                        io.TextIOWrapper(raw, encoding="latin1"), delimiter=";"
                    ):
                        if row["SG_UF"] != "SP":
                            continue
                        office = row["DS_CARGO"].upper()
                        turn = row["NR_TURNO"]
                        name = norm(row["NM_URNA_CANDIDATO"])
                        if office not in (
                            "PRESIDENTE",
                            "GOVERNADOR",
                            "DEPUTADO FEDERAL",
                            "DEPUTADO ESTADUAL",
                            "SENADOR",
                        ):
                            continue
                        # Only the BR member supplies president, preventing duplication.
                        if (suffix == "BR") != (office == "PRESIDENTE"):
                            continue
                        city = norm(row["NM_MUNICIPIO"])
                        if city not in cities:
                            raise ValueError(f"Unmatched TSE municipality: {city}")
                        r = cities[city]
                        v = int(row["QT_VOTOS_NOMINAIS"])
                        valid = int(row["QT_VOTOS_NOMINAIS_VALIDOS"])
                        key = f"{year}_{office}_{turn}"
                        totals[key][name] += v
                        dkey = f"{year}_{office}_{turn}_total"
                        r[dkey] = r.get(dkey, 0) + v
                        selected = None
                        if office == "PRESIDENTE":
                            selected = (
                                "jair"
                                if name == "JAIR BOLSONARO"
                                else (
                                    "pt"
                                    if name in ("LULA", "FERNANDO HADDAD")
                                    else None
                                )
                            )
                        if office == "GOVERNADOR":
                            selected = (
                                "tarcisio"
                                if name in ("TARCISIO", "TARCISIO DE FREITAS")
                                else ("haddad" if name == "FERNANDO HADDAD" else None)
                            )
                        if office.startswith("DEPUTADO"):
                            selected = NAMES.get(name)
                        if selected:
                            k = f"{selected}_{year}_{turn}"
                            r[k] = r.get(k, 0) + v
                            av = f"{selected}_{year}_validos_atualizados"
                            audit[av] = audit.get(av, 0) + valid
        print("TSE", year, flush=True)
    for r in cities.values():
        for year in (2018, 2022):
            for turn in (1, 2):
                r[f"jair_{year}_{turn}_pct"] = (
                    100
                    * r[f"jair_{year}_{turn}"]
                    / r[f"{year}_PRESIDENTE_{turn}_total"]
                )
        for turn in (1, 2):
            r[f"tarcisio_2022_{turn}_pct"] = (
                100
                * r.get(f"tarcisio_2022_{turn}", 0)
                / r[f"2022_GOVERNADOR_{turn}_total"]
            )
        r["mudanca_jair_pp"] = r["jair_2022_2_pct"] - r["jair_2018_2_pct"]
        r["diferenca_governo_presidente_pp"] = (
            r["tarcisio_2022_2_pct"] - r["jair_2022_2_pct"]
        )
        r["virada"] = " → ".join(
            "Jair"
            if r[f"jair_{year}_2"] > r[f"pt_{year}_2"]
            else ("PT" if r[f"jair_{year}_2"] < r[f"pt_{year}_2"] else "Empate")
            for year in (2018, 2022)
        )
    return {k: dict(v) for k, v in totals.items()}, audit


def electorate(cities):
    profile = ROOT / "data/raw/tse_eleitorado/perfil_eleitorado_ATUAL.zip"
    totals = Counter()
    dates = set()
    with zipfile.ZipFile(profile) as z:
        member = next(n for n in z.namelist() if n.endswith(".csv"))
        with z.open(member) as raw:
            for row in csv.DictReader(
                io.TextIOWrapper(raw, encoding="latin1"), delimiter=";"
            ):
                if row["SG_UF"] != "SP":
                    continue
                r = cities[norm(row["NM_MUNICIPIO"])]
                v = int(row["QT_ELEITORES"])
                r["eleitorado"] = r.get("eleitorado", 0) + v
                totals[row["DS_GENERO"]] += v
                dates.add(row["DT_GERACAO"])
    return {
        "sexo": dict(totals),
        "datas_geracao": sorted(dates),
        "total": sum(totals.values()),
    }


def economy(cities):
    import pandas as pd

    path = ROOT / "data/originals/ibge_pib_municipios/base_de_dados_2010_2023_xlsx.zip"
    with zipfile.ZipFile(path) as z:
        data = z.read(z.namelist()[0])
    df = pd.read_excel(io.BytesIO(data), sheet_name="PIB dos Municípios")
    df = df[(df["Sigla da Unidade da Federação"] == "SP") & (df["Ano"] == 2023)]
    vc = next(
        c
        for c in df
        if c.startswith("Produto Interno Bruto,") and "per capita" not in c
    )
    pc = next(c for c in df if c.startswith("Produto Interno Bruto per capita"))
    nc = next(c for c in df if c == "Nome do Município")
    for _, row in df.iterrows():
        r = cities[norm(row[nc])]
        r["pib_2023"] = float(row[vc]) * 1000
        r["pib_pc_2023"] = float(row[pc])


def main():
    (BASE / "fontes").mkdir(parents=True, exist_ok=True)
    (BASE / "derivados").mkdir(parents=True, exist_ok=True)
    PUBLIC.mkdir(parents=True, exist_ok=True)
    cities = geography()
    print("IBGE", len(cities), flush=True)
    totals, audit = elections(cities)
    profile = electorate(cities)
    print("Eleitorado", profile, flush=True)
    economy(cities)
    regs = []
    for name in sorted({r["regiao"] for r in cities.values()}):
        group = [r for r in cities.values() if r["regiao"] == name]
        a = {"nome": name, "municipios": len(group)}
        for k in (
            "eleitorado",
            "populacao",
            "pib_2023",
            "jair_2018_2",
            "jair_2022_2",
            "2018_PRESIDENTE_2_total",
            "2022_PRESIDENTE_2_total",
            "tarcisio_2022_2",
            "2022_GOVERNADOR_2_total",
        ):
            a[k] = sum(r[k] for r in group)
        a["renda_media_municipal_ponderada_pop"] = (
            sum(r["renda"] * r["populacao"] for r in group) / a["populacao"]
        )
        regs.append(a)
    out = {
        "corte": "2026-09-05",
        "municipios": list(cities.values()),
        "regioes": regs,
        "eleitorado": profile,
        "totais_nominais": totals,
        "validos_atualizados_selecionados": audit,
        "fontes": URLS,
        "nota": "Deputados: votos nominais recebidos, não situação jurídica atual; sem votos de legenda. Presidência e governo: totais nominais dos candidatos.",
    }
    (PUBLIC / "sp_092026_data.json").write_text(
        json.dumps(out, ensure_ascii=False, separators=(",", ":")) + "\n"
    )
    fields = sorted(set().union(*(r.keys() for r in cities.values())))
    for path in (
        BASE / "derivados/municipios.csv",
        PUBLIC / "sp_092026_municipios.csv",
    ):
        with path.open("w", encoding="utf-8", newline="") as handle:
            writer = csv.DictWriter(handle, fieldnames=fields, lineterminator="\n")
            writer.writeheader()
            writer.writerows(cities.values())
    print("saved", flush=True)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""PNAD paulista com pesos e réplicas, adaptação explícita do estimador de MG."""

import json
import math
import sqlite3
from pathlib import Path
from statistics import NormalDist

import numpy as np

ROOT = Path(__file__).resolve().parents[1]
PNAD_DB = ROOT / "data/outputs/brasil.sqlite"
REPLICATES = 200
Z95 = NormalDist().inv_cdf(0.975)


def numpy_column(values) -> np.ndarray:
    return np.array(
        [np.nan if value in (None, "") else float(value) for value in values],
        dtype=float,
    )


def replicate_stat(
    theta: float, replicas: np.ndarray, digits: int = 2, key: str = "valor"
) -> dict:
    variance = float(np.sum((replicas - theta) ** 2) / (len(replicas) - 1))
    moe = Z95 * math.sqrt(variance)
    return {
        key: round(theta, digits),
        "moe": round(moe, digits),
        "low": round(theta - moe, digits),
        "high": round(theta + moe, digits),
    }


def weighted_ratio(
    weights: np.ndarray, mask: np.ndarray, universe: np.ndarray, key: str = "pct"
) -> dict:
    num = np.einsum("i,ij->j", mask.astype(float), weights)
    den = np.einsum("i,ij->j", universe.astype(float), weights)
    values = 100 * num / den
    return replicate_stat(float(values[0]), values[1:], 2, key)


def weighted_mean(
    weights: np.ndarray, values: np.ndarray, universe: np.ndarray, key: str = "media"
) -> dict:
    known = universe & np.isfinite(values)
    num = np.einsum("i,ij->j", np.where(known, values, 0.0), weights)
    den = np.einsum("i,ij->j", known.astype(float), weights)
    result = num / den
    return replicate_stat(float(result[0]), result[1:], 2, key)


def fetch_pnad(table: str, fields: list[str], weight_prefix: str):
    replicas = [
        f"{weight_prefix}{index:03d}__peso_replicado_{index}"
        for index in range(1, REPLICATES + 1)
    ]
    weight = f"{weight_prefix}__peso_com_calibracao"
    sql = f'SELECT {",".join(fields)}, {weight}, {",".join(replicas)} FROM "{table}" WHERE UF__unidade_da_federacao=35'
    with sqlite3.connect(f"file:{PNAD_DB}?mode=ro", uri=True) as connection:
        rows = connection.execute(sql).fetchall()
    dims = [
        numpy_column(column)
        for column in zip(*(row[: len(fields)] for row in rows), strict=False)
    ]
    weights = np.array([row[len(fields) :] for row in rows], dtype=float)
    return dims, weights


def read_pnad() -> dict:
    annual_fields = [
        "V2007__sexo",
        "V2009__idade_na_data_de_referencia",
        "VD5001__rend_efetivo_domiciliar_mw",
        "VD5002__rend_efetivo_domiciliar_per_capita_202604",
        "Capital__municipio_da_capital",
        "RM_RIDE__reg_metr_e_reg_adm_int_des",
        "V5002A__recebeu_bolsa_familia",
        "VD5001__rend_efetivo_domiciliar_202604",
    ]
    (sex, age, income_mw, income_pc, capital, metro, bolsa, income_brl), aw = (
        fetch_pnad("base_anual_visita1_labeled_npv", annual_fields, "V1032")
    )
    all_people = np.ones(len(age), dtype=bool)
    adults = age >= 16
    income_known = adults & np.isfinite(income_mw)
    territories = {
        "São Paulo": capital == 35,
        "RM de São Paulo, sem capital": (metro == 35) & (capital != 35),
        "Fora da RM de São Paulo": metro != 35,
    }
    annual = {
        "renda_brl_abril_2026": {
            label: weighted_ratio(
                aw,
                adults
                & np.isfinite(income_brl)
                & (income_brl > low)
                & (income_brl <= high),
                adults & np.isfinite(income_brl),
            )
            for label, low, high in [
                ("Até 2.000", -1, 2000),
                ("2.000 a 3.000", 2000, 3000),
                ("3.000 a 5.000", 3000, 5000),
                ("5.000 a 10.000", 5000, 10000),
                ("Acima de 10.000", 10000, float("inf")),
            ]
        },
        "amostra_pessoas": len(age),
        "amostra_pessoas_16_mais": int(adults.sum()),
        "renda_nao_informada_16_mais_pct": weighted_ratio(
            aw, adults & ~np.isfinite(income_mw), adults
        ),
        "populacao_total": round(float(np.sum(aw[:, 0]))),
        "populacao_16_mais": round(float(np.sum(aw[adults, 0]))),
        "sexo_16_mais": {
            "Mulheres": weighted_ratio(aw, adults & (sex == 2), adults),
            "Homens": weighted_ratio(aw, adults & (sex == 1), adults),
        },
        "idade_16_mais": {
            "16-34": weighted_ratio(aw, (age >= 16) & (age <= 34), adults),
            "35-59": weighted_ratio(aw, (age >= 35) & (age <= 59), adults),
            "60+": weighted_ratio(aw, age >= 60, adults),
        },
        "renda_domiciliar_16_mais": {
            "Até 2 SM": weighted_ratio(
                aw, income_known & (income_mw <= 2), income_known
            ),
            "Mais de 2 a 5 SM": weighted_ratio(
                aw, income_known & (income_mw > 2) & (income_mw <= 5), income_known
            ),
            "Mais de 5 SM": weighted_ratio(
                aw, income_known & (income_mw > 5), income_known
            ),
        },
        "renda_pc_media_todos_abril_2026": weighted_mean(aw, income_pc, all_people),
        "declarantes_recebimento_bolsa_familia_pct": weighted_ratio(
            aw, bolsa == 1, all_people
        ),
        "territorios": {},
    }
    for name, mask in territories.items():
        annual["territorios"][name] = {
            "populacao_pct": weighted_ratio(aw, mask, all_people),
            "renda_pc_media_abril_2026": weighted_mean(aw, income_pc, mask),
            "declarantes_recebimento_bolsa_familia_pct": weighted_ratio(
                aw, mask & (bolsa == 1), mask
            ),
        }

    quarter_fields = [
        "V2009__idade_na_data_de_referencia",
        "VD3004__nivel_de_instrucao_mais_elevado_alcancado_5_anos_ou_mais_de_idade",
        "VD4001__condicao_em_relacao_forca_d_trab",
        "VD4002__condicao_de_ocupacao",
        "VD4009__posicao_na_ocupacao_trab_princ",
        "VD4020__rendim_efetivo_qq_trabalho_202604",
        "Capital__municipio_da_capital",
        "RM_RIDE__reg_metr_e_reg_adm_int_des",
    ]
    (
        (
            q_age,
            school,
            labor_force,
            employed,
            _position,
            work_income,
            _q_capital,
            _q_metro,
        ),
        qw,
    ) = fetch_pnad("base_labeled_npv", quarter_fields, "V1028")
    q_adults = q_age >= 16
    labor = q_adults & (labor_force == 1)
    occupied = q_adults & (employed == 1)
    quarter = {
        "escolaridade_16_mais": {
            "Até fundamental completo": weighted_ratio(
                qw, q_adults & (school >= 1) & (school <= 3), q_adults
            ),
            "Médio incompleto ou completo": weighted_ratio(
                qw, q_adults & (school >= 4) & (school <= 5), q_adults
            ),
            "Superior incompleto ou completo": weighted_ratio(
                qw, q_adults & (school >= 6), q_adults
            ),
        },
        "participacao_trabalho_16_mais_pct": weighted_ratio(qw, labor, q_adults),
        "ocupacao_16_mais_pct": weighted_ratio(qw, occupied, q_adults),
        "desocupacao_forca_trabalho_pct": weighted_ratio(
            qw, labor & (employed == 2), labor
        ),
        "renda_media_trabalho_ocupados_abril_2026": weighted_mean(
            qw, work_income, occupied
        ),
    }
    return {
        "anual_2025_visita1": annual,
        "trimestral_2026_t1": quarter,
        "metodo": {
            "universo": "São Paulo; indicadores eleitorais e de renda da amostra restritos a 16 anos ou mais quando indicado",
            "pesos": "V1032 na anual 2025 e V1028 no trimestre 2026 T1",
            "incerteza": "IC 95% pelas 200 réplicas oficiais; variância = soma((theta_r-theta)^2)/(R-1)",
            "monetarios": "valores deflacionados para abril de 2026; SM alvo R$ 1.621",
            "bolsa_familia": "Pessoas que declararam receber o benefício; não mede moradores de domicílios beneficiários.",
        },
    }


if __name__ == "__main__":
    result = read_pnad()
    path = ROOT / "docs/assets/sp_092026_pnad.json"
    path.write_text(json.dumps(result, ensure_ascii=False, indent=2) + "\n")
    print(path)

